function o(t){return!!t?.isVariable&&!!t?.skipWorkProcess&&t?.trackInventory!==!1}function a(t){const n=Math.floor(Number(t)||1);return n>=1?n:1}function s(t){return o(t)?(Number(t.stockQuantity)||0)<=0:!1}function i(t){if(!o(t))return null;const n=Number(t.stockQuantity)||0;if(n<=0)return"Out of stock";const r=Number(t.lowStockThreshold),u=Number.isFinite(r)?r:5;return n<=u?`Low stock: ${n} left`:`${n} in stock`}function l(t){return o(t)?Math.max(0,Math.floor(Number(t.stockQuantity)||0)):null}export{o as a,s as i,a as l,l as m,i as s};
